<style>
:root{--night:#10243a;--deep:#091724;--paper:#f3ead5;--ink:#18304a;--gold:#f1bd4a;--coral:#e86f51;--mint:#91c6ad;--blue:#7eb8d4;--line:rgba(241,189,74,.35)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--night);color:var(--paper);font-family:"Palatino Linotype",Palatino,"Book Antiqua",serif;line-height:1.5;overflow-x:hidden}button{font:inherit;touch-action:manipulation}
.hero{position:relative;min-height:min(760px,92vh);display:grid;align-items:end;overflow:hidden;border-bottom:1px solid var(--line)}
.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,23,36,.96),rgba(9,23,36,.72) 42%,rgba(9,23,36,.08) 75%),linear-gradient(0deg,var(--night),transparent 44%),url('little-rule-workshop-hero.webp') center/cover no-repeat;transform:scale(1.01)}
.hero:after{content:"";position:absolute;inset:0;opacity:.1;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 140 140' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")}
.hero-copy{position:relative;z-index:1;width:min(1160px,100%);margin:auto;padding:clamp(34px,7vw,88px) clamp(20px,5vw,68px)}
.eyebrow,.kicker{color:var(--gold);text-transform:uppercase;letter-spacing:.17em;font:800 .7rem "Trebuchet MS",sans-serif}.eyebrow{display:flex;align-items:center;gap:11px}.eyebrow:before{content:"";width:40px;height:1px;background:currentColor}
h1{font-weight:400;font-size:clamp(3.3rem,9vw,7.5rem);letter-spacing:-.065em;line-height:.79;max-width:770px;margin:.22em 0 .28em;text-wrap:balance}h1 em{font-weight:400;color:var(--gold)}
.lede{max-width:590px;font-size:clamp(1.08rem,2vw,1.35rem);color:#d8e0df;margin:0 0 26px}
